#include <iostream>
#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "../../../../csrc_base/ops_common.h"
using torch::autograd::AutogradContext;
using torch::autograd::Function;
using variable_list = std::vector<at::Tensor>;

namespace custom {
using namespace at_npu::native;

// 为NPU设备实现前向接口
at::Tensor npu_aggregate_hidden_npu(
    const at::Tensor &input, const at::Tensor &weight, const c10::optional<at::Tensor> &mask)
{
    // 1. 准备输出张量
    std::vector<c10::SymInt> output_size{input.size(0), input.size(1), input.size(2)};
    at::Tensor output = at::empty_symint(output_size, input.options());

    // 2. 调用NPU算子
    EXEC_NPU_CMD_V1(aclnnAiInfraAggregateHidden, input, weight, mask, output);  // mask为空直接传

    return std::move(output);
}

// 为NPU设备实现反向接口
::std::tuple<at::Tensor, at::Tensor> npu_aggregate_hidden_grad_npu(const at::Tensor &grad_output,
    const at::Tensor &input, const at::Tensor &weight, const c10::optional<at::Tensor> &mask)
{
    // 准备输出张量
    std::vector<c10::SymInt> grad_input_size{input.size(0), input.size(1), input.size(2)};
    std::vector<c10::SymInt> grad_weight_size{weight.size(0), weight.size(1)};
    auto grad_input = at::empty_symint(grad_input_size, input.options());
    auto grad_weight = at::empty_symint(grad_weight_size, input.options());

    // 调用NPU反向算子
    EXEC_NPU_CMD_V1(aclnnAiInfraAggregateHiddenGrad, grad_output, input, weight, mask, grad_input, grad_weight);

    return std::make_tuple(std::move(grad_input), std::move(grad_weight));
}

// Autograd Function类
class AiInfraAggregateHiddenFunction : public torch::autograd::Function<AiInfraAggregateHiddenFunction> {
public:
    static variable_list forward(
        AutogradContext *ctx, const at::Tensor &input, const at::Tensor &weight, const c10::optional<at::Tensor> &mask)
    {
        at::AutoDispatchBelowADInplaceOrView guard;  // 避免递归调用AD

        // 1. 查找并调用注册的NPU前向算子
        static auto op = torch::Dispatcher::singleton()
                             .findSchemaOrThrow("custom::npu_aggregate_hidden", "")
                             .typed<decltype(npu_aggregate_hidden_npu)>();

        at::Tensor output = op.call(input, weight, mask);

        // 2. 保存前向输出
        ctx->save_for_backward({output.detach(), input, weight, mask.value_or(at::Tensor())});

        // 3. 返回前向输出
        return {output};
    }

    static variable_list backward(AutogradContext *ctx, variable_list grad_outputs)
    {
        // 1. 恢复前向保存的变量
        auto saved = ctx->get_saved_variables();
        at::Tensor output = saved[0];  // 前向输出
        at::Tensor input = saved[1];
        at::Tensor weight = saved[2];

        // 恢复mask（如果存在）
        c10::optional<at::Tensor> mask = saved[3].defined() ? c10::optional<at::Tensor>(saved[3]) : c10::nullopt;

        // 2. 梯度处理
        at::Tensor grad = grad_outputs[0];
        if (grad_outputs.size() > 0 && grad.defined()) {
            grad = grad.contiguous();  // 确保梯度内存连续（NPU算子要求）
        } else {
            grad = at::zeros_like(output);  // 梯度未定义时补0
        }

        // 3. 查找并调用注册的NPU反向算子
        static auto op = torch::Dispatcher::singleton()
                             .findSchemaOrThrow("custom::npu_aggregate_hidden_grad", "")
                             .typed<decltype(npu_aggregate_hidden_grad_npu)>();

        auto grads = op.call(grad, input, weight, mask);

        // 4. 返回梯度列表
        at::Tensor input_grad = std::get<0>(grads);
        at::Tensor weight_grad = std::get<1>(grads);

        return {
            input_grad,   // input的梯度
            weight_grad,  // weight的梯度
            at::Tensor()  // mask的梯度（None，因为mask不参与梯度计算）
        };
    }
};

// Autograd包装函数
at::Tensor npu_aggregate_hidden_autograd(
    const at::Tensor &input, const at::Tensor &weight, const c10::optional<at::Tensor> &mask)
{
    variable_list outputs = AiInfraAggregateHiddenFunction::apply(input, weight, mask);

    return outputs[0];  // 只返回单个输出张量 output
}

// 为Meta设备实现前向接口
at::Tensor npu_aggregate_hidden_meta(
    const at::Tensor &input, const at::Tensor &weight, const c10::optional<at::Tensor> &mask)
{
    std::vector<c10::SymInt> output_size{input.size(0), input.size(1), input.size(2)};
    at::Tensor output = at::empty_symint(output_size, input.options());

    return std::move(output);
}

}  // namespace custom

// 为NPU设备注册实现
TORCH_LIBRARY_IMPL(custom, PrivateUse1, m)
{
    m.impl("npu_aggregate_hidden", &custom::npu_aggregate_hidden_npu);
    m.impl("npu_aggregate_hidden_grad", &custom::npu_aggregate_hidden_grad_npu);
}

TORCH_LIBRARY_IMPL(custom, AutogradPrivateUse1, m)
{
    m.impl("npu_aggregate_hidden", &custom::npu_aggregate_hidden_autograd);
}

// 为Meta设备注册实现
TORCH_LIBRARY_IMPL(custom, Meta, m)
{
    m.impl("npu_aggregate_hidden", &custom::npu_aggregate_hidden_meta);
}

