232	inline std::vector<std::string> get_default_custom_lib_path()
233	{
234	    char *ascend_opp_path = std::getenv("ASCEND_OPP_PATH");
235	    std::vector<std::string> default_vendors_list;
236	
237	    if (ascend_opp_path == nullptr) {
238	        ASCEND_LOGW("ASCEND_OPP_PATH is not exists");
239	        return std::vector<std::string>();
240	    }
241	
242	    std::string vendors_path(ascend_opp_path);
243	    vendors_path = vendors_path + "/vendors";
244	    std::string vendors_config_file = real_path(vendors_path + "/config.ini");
245	    if (vendors_config_file.empty()) {
246	        ASCEND_LOGW("config.ini is not exists");
247	        return std::vector<std::string>();
248	    }
249	
250	    if (!is_file_exist(vendors_config_file)) {
251	        ASCEND_LOGW("config.ini is not exists or the path length is more than %d", PATH_MAX);
252	        return std::vector<std::string>();
253	    }
254	
255	    std::ifstream ifs(vendors_config_file);
256	    std::string line;
257	    while (std::getline(ifs, line)) {
258	        if (line.find("load_priority=") == 0) {
259	            break;
260	        }
261	    }
262	    std::string head = "load_priority=";
263	    line.erase(0, head.length());
264	
265	    // split string with ","
266	    default_vendors_list = split_str(line, ",");
267	    if (default_vendors_list.empty()) {
268	        return std::vector<std::string>();
269	    }
270	    for (auto &it : default_vendors_list) {
271	        it = real_path(vendors_path + "/" + it + "/op_api/lib/");
272	    }
273	
274	    return default_vendors_list;
275	}
