324	
325	inline void *GetOpApiFuncAddr(const char *apiName)
326	{
327	    if (!g_custom_lib_path.empty()) {
328	        for (auto &it : g_custom_lib_path) {
329	            auto cust_opapi_lib = real_path(it + "/" + GetCustOpApiLibName());
330	            if (cust_opapi_lib.empty()) {
331	                continue;
332	            }
333	            auto custOpApiHandler = GetOpApiLibHandler(cust_opapi_lib.c_str());
334	            if (custOpApiHandler != nullptr) {
335	                auto funcAddr =
336	                    GetOpApiFuncAddrInLib(custOpApiHandler, GetCustOpApiLibName(), apiName);
337	                if (funcAddr != nullptr) {
338	                    ASCEND_LOGI("%s is found in %s.", apiName, cust_opapi_lib.c_str());
339	                    return funcAddr;
340	                }
341	            }
342	        }
343	        ASCEND_LOGI("%s is not in custom lib.", apiName);
344	    }
345	
346	    if (!g_default_custom_lib_path.empty()) {
347	        for (auto &it : g_default_custom_lib_path) {
348	            auto default_cust_opapi_lib = real_path(it + "/" + GetCustOpApiLibName());
349	            if (default_cust_opapi_lib.empty()) {
350	                continue;
351	            }
352	            auto custOpApiHandler = GetOpApiLibHandler(default_cust_opapi_lib.c_str());
353	            if (custOpApiHandler != nullptr) {
354	                auto funcAddr =
355	                    GetOpApiFuncAddrInLib(custOpApiHandler, GetCustOpApiLibName(), apiName);
356	                if (funcAddr != nullptr) {
357	                    ASCEND_LOGI("%s is found in %s.", apiName, default_cust_opapi_lib.c_str());
358	                    return funcAddr;
359	                }
360	            }
361	        }
362	        ASCEND_LOGI("%s is not in default custom lib.", apiName);
363	    }
364	
365	    GET_OP_API_FUNC_FROM_FEATURE_LIB(opapiMathHandler, "libopapi_math.so", apiName);
366	    GET_OP_API_FUNC_FROM_FEATURE_LIB(opapiNnHandler, "libopapi_nn.so", apiName);
367	    GET_OP_API_FUNC_FROM_FEATURE_LIB(opapiCvHandler, "libopapi_cv.so", apiName);
368	    GET_OP_API_FUNC_FROM_FEATURE_LIB(opapiTransformerHandler, "libopapi_transformer.so", apiName);
369	    GET_OP_API_FUNC_FROM_FEATURE_LIB(opapiLegacyHandler, "libopapi_legacy.so", apiName);
370	
371	    static auto opApiHandler = GetOpApiLibHandler(GetOpApiLibName());
372	    if (opApiHandler != nullptr) {
373	        auto funcAddr = GetOpApiFuncAddrInLib(opApiHandler, GetOpApiLibName(), apiName);
374	        if (funcAddr != nullptr) {
375	            return funcAddr;
376	        }
377	    }
378	    return GetOpApiFuncAddrFromFeatureLib(apiName);
379	}
