383	inline c10::Scalar ConvertTensorToScalar(const at::Tensor &tensor)
384	{
385	  c10::Scalar expScalar;
386	  const at::Tensor *aclInput = &tensor;
387	  if (aclInput->scalar_type() == at::ScalarType::Double) {
388	    double value = *(double *)aclInput->data_ptr();
389	    c10::Scalar scalar(value);
390	    expScalar = scalar;
391	  } else if (aclInput->scalar_type() == at::ScalarType::Long) {
392	    int64_t value = *(int64_t *)aclInput->data_ptr();
393	    c10::Scalar scalar(value);
394	    expScalar = scalar;
395	  } else if (aclInput->scalar_type() == at::ScalarType::Float) {
396	    float value = *(float *)aclInput->data_ptr();
397	    c10::Scalar scalar(value);
398	    expScalar = scalar;
399	  } else if (aclInput->scalar_type() == at::ScalarType::Int) {
400	    int value = *(int *)aclInput->data_ptr();
401	    c10::Scalar scalar(value);
402	    expScalar = scalar;
403	  } else if (aclInput->scalar_type() == at::ScalarType::Half) {
404	    c10::Half value = *(c10::Half *)aclInput->data_ptr();
405	    c10::Scalar scalar(value);
406	    expScalar = scalar;
407	  } else if (aclInput->scalar_type() == at::ScalarType::Bool) {
408	    int8_t value = *(int8_t *)aclInput->data_ptr();
409	    c10::Scalar scalar(value);
410	    expScalar = scalar;
411	  } else if (aclInput->scalar_type() == at::ScalarType::ComplexDouble) {
412	    c10::complex<double> value = *(c10::complex<double> *)aclInput->data_ptr();
413	    c10::Scalar scalar(value);
414	    expScalar = scalar;
415	  } else if (aclInput->scalar_type() == at::ScalarType::ComplexFloat) {
416	    c10::complex<float> value = *(c10::complex<float> *)aclInput->data_ptr();
417	    c10::Scalar scalar(value);
418	    expScalar = scalar;
419	  } else if (aclInput->scalar_type() == at::ScalarType::BFloat16) {
420	    c10::BFloat16 value = *(c10::BFloat16 *)aclInput->data_ptr();
421	    c10::Scalar scalar(value);
422	    expScalar = scalar;
423	  }
424	  return expScalar;
425	}
