441	static bool IsOpInputBaseFormatCommon(const at::Tensor &at_tensor)
442	{
443	  if (!torch_npu::utils::is_npu(at_tensor)) {
444	    return true;
445	  }
446	  const auto format = static_cast<NPUStorageImpl *>(at_tensor.storage().unsafeGetStorageImpl())->npu_desc_.npu_format_;
447	  return (format == ACL_FORMAT_ND) || (format == ACL_FORMAT_NCHW) || (format == ACL_FORMAT_NHWC) ||
448	      (format == ACL_FORMAT_NCDHW);
449	}
