451	inline aclTensor *ConvertType(const at::Tensor &at_tensor)
452	{
453	  static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
454	  if (aclCreateTensor == nullptr) {
455	    return nullptr;
456	  }
457	
458	  if (!at_tensor.defined()) {
459	    return nullptr;
460	  }
461	  at::ScalarType scalar_data_type = at_tensor.scalar_type();
462	  aclDataType acl_data_type =
463	      kATenScalarTypeToAclDataTypeTable[static_cast<int64_t>(scalar_data_type)];
464	  TORCH_CHECK(
465	      acl_data_type != ACL_DT_UNDEFINED,
466	      std::string(c10::toString(scalar_data_type)) + " has not been supported")
467	  c10::SmallVector<int64_t, SIZE> storageDims;
468	
469	  const auto dimNum = at_tensor.sizes().size();
470	  aclFormat format = ACL_FORMAT_ND;
471	  if (!IsOpInputBaseFormatCommon(at_tensor)) {
472	    format = static_cast<NPUStorageImpl *>(at_tensor.storage().unsafeGetStorageImpl())->npu_desc_.npu_format_;
473	    if (acl_data_type != ACL_STRING) {
474	        TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.");
475	        storageDims = static_cast<NPUStorageImpl *>(
476	                          at_tensor.storage().unsafeGetStorageImpl())
477	                          ->npu_desc_.storage_sizes_;
478	    }
479	  } else {
480	    switch (dimNum) {
481	        case 3:
482	            format = ACL_FORMAT_NCL;
483	            break;
484	        case 4:
485	            format = ACL_FORMAT_NCHW;
486	            break;
487	        case 5:
488	            format = ACL_FORMAT_NCDHW;
489	            break;
490	        default:
491	            format = ACL_FORMAT_ND;
492	    }
493	    if (acl_data_type != ACL_STRING) {
494	        TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.");
495	        storageDims.push_back(at_tensor.storage().nbytes() / at_tensor.itemsize());
496	    }
497	  }
498	
499	  if (at_tensor.unsafeGetTensorImpl()->is_wrapped_number()) {
500	    // no need this ConvertTensorToScalar
501	    c10::Scalar expScalar = at_tensor.item();
502	    at::Tensor aclInput = CopyScalarToDevice(expScalar, scalar_data_type);
503	    return aclCreateTensor(aclInput.sizes().data(), aclInput.sizes().size(),
504	                           acl_data_type, aclInput.strides().data(),
505	                           aclInput.storage_offset(), format,
506	                           storageDims.data(), storageDims.size(),
507	                           const_cast<void *>(aclInput.storage().data()));
508	  }
509	
510	  auto acl_tensor = aclCreateTensor(
511	      at_tensor.sizes().data(), at_tensor.sizes().size(), acl_data_type,
512	      at_tensor.strides().data(), at_tensor.storage_offset(), format,
513	      storageDims.data(), storageDims.size(),
514	      const_cast<void *>(at_tensor.storage().data()));
515	  return acl_tensor;
516	}
