518	inline aclScalar *ConvertType(const at::Scalar &at_scalar)
519	{
520	    static const auto aclCreateScalar = GET_OP_API_FUNC(aclCreateScalar);
521	    if (aclCreateScalar == nullptr) {
522	        return nullptr;
523	    }
524	
525	    at::ScalarType scalar_data_type = at_scalar.type();
526	    aclDataType acl_data_type =
527	        kATenScalarTypeToAclDataTypeTable[static_cast<int64_t>(scalar_data_type)];
528	    TORCH_CHECK(
529	        acl_data_type != ACL_DT_UNDEFINED,
530	        std::string(c10::toString(scalar_data_type)) + " has not been supported")
531	    aclScalar *acl_scalar = nullptr;
532	    switch (scalar_data_type) {
533	        case at::ScalarType::Double: {
534	            double value = at_scalar.toDouble();
535	            acl_scalar = aclCreateScalar(&value, acl_data_type);
536	            break;
537	        }
538	        case at::ScalarType::Long: {
539	            int64_t value = at_scalar.toLong();
540	            acl_scalar = aclCreateScalar(&value, acl_data_type);
541	            break;
542	        }
543	        case at::ScalarType::Bool: {
544	            bool value = at_scalar.toBool();
545	            acl_scalar = aclCreateScalar(&value, acl_data_type);
546	            break;
547	        }
548	        case at::ScalarType::ComplexDouble: {
549	            auto value = at_scalar.toComplexDouble();
550	            acl_scalar = aclCreateScalar(&value, acl_data_type);
551	            break;
552	        }
553	        default:
554	            acl_scalar = nullptr;
555	            break;
556	    }
557	    return acl_scalar;
558	}
