690	
691	inline aclTensor *ConvertType(const TensorWrapper &tensor_r)
692	{
693	    static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
694	    if (aclCreateTensor == nullptr) {
695	        return nullptr;
696	    }
697	
698	    const at::Tensor &at_tensor = tensor_r.tensor_;
699	
700	    if (!at_tensor.defined()) {
701	        return nullptr;
702	    }
703	    TORCH_CHECK(torch_npu::utils::is_npu(at_tensor),
704	        "Expected all tensors to be on the same device. "
705	        "Expected NPU tensor, please check whether the input tensor device is correct.",
706	        OPS_ERROR(ErrCode::TYPE));
707	
708	    aclDataType acl_data_type = tensor_r.dtype;
709	    c10::SmallVector<int64_t, MAX_DIM_NUM> storageDims;
710	    c10::SmallVector<int64_t, MAX_DIM_NUM> wrapperStride = array_to_small_vector(at_tensor.strides());
711	    c10::SmallVector<int64_t, MAX_DIM_NUM> wrapperShape = array_to_small_vector(at_tensor.sizes());
712	
713	    const auto dimNum = at_tensor.sizes().size();
714	    aclFormat format = ACL_FORMAT_ND;
715	    if (!at_npu::native::FormatHelper::IsOpInputBaseFormat(at_tensor)) {
716	        format = torch_npu::NPUBridge::GetNpuStorageImpl(at_tensor)->npu_desc_.npu_format_;
717	        // if acl_data_type is ACL_STRING, storageDims is empty.
718	        if (acl_data_type != ACL_STRING) {
719	            TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.",
720	                OPS_ERROR(ErrCode::VALUE));
721	            storageDims = torch_npu::NPUBridge::GetNpuStorageImpl(at_tensor)->npu_desc_.storage_sizes_;
722	        }
723	    } else {
724	        switch (dimNum) {
725	            case NCL_DIM_NUM:
726	                format = ACL_FORMAT_NCL;
727	                break;
728	            case NCHW_DIM_NUM:
729	                format = ACL_FORMAT_NCHW;
730	                break;
731	            case NCDHW_DIM_NUM:
732	                format = ACL_FORMAT_NCDHW;
733	                break;
734	            default:
735	                format = ACL_FORMAT_ND;
736	        }
737	        // if acl_data_type is ACL_STRING, storageDims is empty.
738	        if (acl_data_type != ACL_STRING) {
739	            TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.",
740	                        OPS_ERROR(ErrCode::VALUE));
741	            storageDims.push_back(at_tensor.storage().nbytes() / at_tensor.itemsize());
742	        }
743	    }
744	
745	    auto acl_tensor =
746	        aclCreateTensor(wrapperShape.data(), at_tensor.sizes().size(), acl_data_type, wrapperStride.data(),
747	                        at_tensor.storage_offset(), format, storageDims.data(), storageDims.size(),
748	                        const_cast<void *>(at_tensor.storage().data()));
749	    return acl_tensor;
750	}
