970	        static const auto unInitMemAddr = GetOpApiFuncAddr("UnInitHugeMemThreadLocal");                                \
971	        static const auto releaseMemAddr = GetOpApiFuncAddr("ReleaseHugeMem");                                         \
972	        static const auto initPTACacheThreadLocalAddr = GetOpApiFuncAddr("InitPTACacheThreadLocal");                   \
973	        static const auto setPTAHashKeyAddr = GetOpApiFuncAddr("SetPTAHashKey");                                       \
974	        TORCH_CHECK(getWorkspaceSizeFuncAddr != nullptr && opApiFuncAddr != nullptr, #aclnn_api, " or ",               \
975	                    #aclnn_api "GetWorkspaceSize", " not in ", GetOpApiLibName(), ", or ", GetOpApiLibName(),          \
976	                    "not found.");                                                                                     \
977	        auto acl_stream = c10_npu::getCurrentNPUStream().stream(false);                                                \
978	        uint64_t workspace_size = 0;                                                                                   \
979	        uint64_t *workspace_size_addr = &workspace_size;                                                               \
980	        aclOpExecutor *executor = nullptr;                                                                             \
