983	        UnInitHugeMemThreadLocal unInitMemFunc = reinterpret_cast<UnInitHugeMemThreadLocal>(unInitMemAddr);            \
984	        GetDeterministic();                                                                                            \
985	        InitPTACacheThreadLocal initPTACacheThreadLocalFunc =                                                          \
986	            reinterpret_cast<InitPTACacheThreadLocal>(initPTACacheThreadLocalAddr);                                    \
987	        SetPTAHashKey setPTAHashKeyFunc = reinterpret_cast<SetPTAHashKey>(setPTAHashKeyAddr);                          \
988	        if (initPTACacheThreadLocalFunc && setPTAHashKeyFunc) {                                                        \
989	            initPTACacheThreadLocalFunc();                                                                             \
990	            setPTAHashKeyFunc(0);                                                                                      \
991	        }                                                                                                              \
992	        if (initMemFunc) {                                                                                             \
993	            initMemFunc(nullptr, false);                                                                               \
994	        }                                                                                                              \
