996	        static auto getWorkspaceSizeFunc = ConvertToOpApiFunc(converted_params, getWorkspaceSizeFuncAddr);             \
997	        auto workspace_status = call(getWorkspaceSizeFunc, converted_params);                                          \
998	        TORCH_CHECK(workspace_status== 0, "call " #aclnn_api " failed");                                               \
999	        void *workspace_addr = nullptr;                                                                                \
