1006	            workspace_addr = const_cast<void *>(workspace_tensor.storage().data());                                    \
1007	        }                                                                                                              \
1008	        auto acl_call = [converted_params, workspace_addr, workspace_size, acl_stream, executor]()->int {              \
1009	            OpApiFunc opApiFunc = reinterpret_cast<OpApiFunc>(opApiFuncAddr);                                          \
1010	            auto api_ret = opApiFunc(workspace_addr, workspace_size, executor, acl_stream);                            \
