#include <iostream>
#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "../../../../csrc_base/ops_common.h"

using variable_list = std::vector<at::Tensor>;

namespace custom {
    const static int64_t DIM_0 = 0;
    const static int64_t DIM_1 = 1;
    const static int64_t DIM_2 = 2;
    const static int64_t DIM_3 = 3;

    using namespace at_npu::native;

    std::tuple<at::Tensor, at::Tensor, at::Tensor> construct_sinkhorn_output_tensor(
        const at::Tensor& x,
        int64_t out_flag,
        double eps,
        int64_t num_iters)
    {
        // ========== 1. 输入维度基础校验 ==========
        TORCH_CHECK(x.dim() == 3 || x.dim() == 4, 
                    "Sinkhorn input x must be 3D [T,n,n] or 4D [B,S,n,n], but got ", x.dim(), "D");

        // 校验最后两个维度为方阵（n×n）
        c10::SymInt n = x.sym_size(DIM_2);
        c10::SymInt last_dim = x.sym_size(x.dim() - 1);
        TORCH_CHECK(n == last_dim, 
                    "Last two dimensions of x must be equal (n×n matrix), but got ", n, " and ", last_dim);
        TORCH_CHECK(n > 0, "Matrix dimension n must be greater than 0, but got ", n);
        TORCH_CHECK(num_iters > 0, "num_iters must be greater than 0, but got ", num_iters);

        // ========== 2. 构建output==========
        c10::SmallVector<c10::SymInt> x_shape;
        for (int i = 0; i < x.dim(); i++) {
            x_shape.push_back(x.sym_size(i));
        }
        at::Tensor output = at::empty_symint(x_shape, x.options());

        // ========== 3. 构建norm_out ==========
        at::Tensor norm_out;
        c10::SymInt iter_dim = 2 * c10::SymInt(num_iters);
        if (out_flag != 0) {
            c10::SmallVector<c10::SymInt> norm_out_shape;
            if (x.dim() == 4) { // 4: 表示维度，支持B,S,N,N四维shape
                c10::SymInt B = x.sym_size(DIM_0);
                c10::SymInt S = x.sym_size(DIM_1);
                c10::SymInt n_sym = c10::SymInt(n);
                norm_out_shape = {iter_dim, n_sym, n_sym, B, S};
            } else {
                c10::SymInt T = x.sym_size(DIM_0);
                c10::SymInt n_sym = c10::SymInt(n);
                norm_out_shape = {iter_dim, n_sym, n_sym, T};
            }
            norm_out = at::empty_symint(norm_out_shape, x.options().dtype(x.scalar_type()));
        } else {
            c10::SmallVector<c10::SymInt> empty_shape = {c10::SymInt(0)};
            norm_out = at::empty_symint(empty_shape, x.options());
        }

        // ========== 4. 构建sum_out ==========
        at::Tensor sum_out;
        if (out_flag != 0) {
            c10::SmallVector<c10::SymInt> sum_out_shape;
            if (x.dim() == 4) { // 4: 表示维度，支持B,S,N,N四维shape
                c10::SymInt B = x.sym_size(DIM_0);
                c10::SymInt S = x.sym_size(DIM_1);
                c10::SymInt n_sym = c10::SymInt(n);
                sum_out_shape = {iter_dim, n_sym, B, S};
            } else {
                c10::SymInt T = x.sym_size(DIM_0);
                c10::SymInt n_sym = c10::SymInt(n);
                sum_out_shape = {iter_dim, n_sym, T};
            }
            sum_out = at::empty_symint(sum_out_shape, x.options().dtype(x.scalar_type()));
        } else {
            c10::SmallVector<c10::SymInt> empty_shape = {c10::SymInt(0)};
            sum_out = at::empty_symint(empty_shape, x.options());
        }

        return std::make_tuple(output, norm_out, sum_out);
    }

    // 为NPU设备实现前向接口
    std::tuple<at::Tensor, at::Tensor, at::Tensor> npu_sinkhorn_npu(
        const at::Tensor& x,
        int64_t out_flag,
        double eps,
        int64_t num_iters)
    {
        TORCH_CHECK(x.numel() > 0, "Tensor x is empty (numel=0).");
        // 1. 构建输出张量
        auto sinkhorn_output = custom::construct_sinkhorn_output_tensor(x, out_flag, eps, num_iters);
        at::Tensor output = std::get<0>(sinkhorn_output);
        at::Tensor norm_out = std::get<1>(sinkhorn_output);
        at::Tensor sum_out = std::get<2>(sinkhorn_output);

        // 2. 调用NPU内核
        EXEC_NPU_CMD_V1(aclnnManifoldConstrainedHyperConnectionSinkhornEnhance, x, out_flag, eps, num_iters,
                        output, norm_out, sum_out);

        return std::make_tuple(output, norm_out, sum_out);
    }

    // 为Meta设备实现前向接口
    std::tuple<at::Tensor, at::Tensor, at::Tensor> npu_sinkhorn_meta(
        const at::Tensor& x,
        int64_t out_flag,
        double eps,
        int64_t num_iters)
    {
        // 1. 构建输出张量
        auto sinkhorn_output = custom::construct_sinkhorn_output_tensor(x, out_flag, eps, num_iters);
        at::Tensor output = std::get<0>(sinkhorn_output);
        at::Tensor norm_out = std::get<1>(sinkhorn_output);
        at::Tensor sum_out = std::get<2>(sinkhorn_output);

        return std::make_tuple(output, norm_out, sum_out);
    }

} // namespace custom

// 注册前向实现
TORCH_LIBRARY_IMPL(custom, PrivateUse1, m) {
    m.impl("npu_sinkhorn", &custom::npu_sinkhorn_npu);
}

// 注册Meta模式实现
TORCH_LIBRARY_IMPL(custom, Meta, m) {
    m.impl("npu_sinkhorn", &custom::npu_sinkhorn_meta);
}

